/* Host side of the ILP32 original-engine module (see original_engine.h).
 *
 * core32.c is the wasm2c translation of the original sources (generated by
 * tools/build_core32.py); this file instantiates it, owns its linear memory and
 * binds the module imports. Imports not bound here are emitted by the
 * generator into core32_gaps.c and report themselves through recvx_core32_gap.
 */
#include "original_engine.h"
#include "core32.h"
#include "core_random.h"
#include <math.h>
#include <stdio.h>
#include <string.h>

struct w2c_env { int unused; };

static struct w2c_env env;
static wasm_rt_memory_t memory;
static w2c_core32 instance;
static int ready;
static RECVX_ORIGINAL_HOST host;
static uint32_t current_texlist;

/* ---- gap registry ---------------------------------------------------------- */
enum { GAP_MAX = 128 };
static const char* gap_names[GAP_MAX];
static unsigned gap_calls[GAP_MAX];
static int gap_n;

void recvx_core32_gap(const char* name)
{
    for (int i = 0; i < gap_n; ++i)
        if (gap_names[i] == name || strcmp(gap_names[i], name) == 0) { ++gap_calls[i]; return; }
    if (gap_n < GAP_MAX) { gap_names[gap_n] = name; gap_calls[gap_n] = 1; ++gap_n; }
}
int recvx_original_gap_count(void) { return gap_n; }
const char* recvx_original_gap(int index, unsigned* calls)
{
    if (index < 0 || index >= gap_n) return NULL;
    if (calls) *calls = gap_calls[index];
    return gap_names[index];
}

/* ---- memory helpers ---------------------------------------------------------- */
static uint8_t* mem_at(uint32_t address) { return memory.data + address; }
static uint32_t read_u32(uint32_t address) { uint32_t v; memcpy(&v, mem_at(address), 4); return v; }
static const char* mem_string(uint32_t address)
{
    if (address >= memory.size) return "";
    return (const char*)mem_at(address);
}

/* ---- imports ----------------------------------------------------------------- */
wasm_rt_memory_t* w2c_env_memory(struct w2c_env* e) { (void)e; return &memory; }

/* libm: value-only functions of the EE libm. */
f32 w2c_env_sinf(struct w2c_env* e, f32 x) { (void)e; return sinf(x); }
f32 w2c_env_tanf(struct w2c_env* e, f32 x) { (void)e; return tanf(x); }
f32 w2c_env_acosf(struct w2c_env* e, f32 x) { (void)e; return acosf(x); }
f32 w2c_env_asinf(struct w2c_env* e, f32 x) { (void)e; return asinf(x); }
f32 w2c_env_atan2f(struct w2c_env* e, f32 y, f32 x) { (void)e; return atan2f(y, x); }
f32 w2c_env_powf(struct w2c_env* e, f32 x, f32 y) { (void)e; return powf(x, y); }
/* EE libc rand (0x00125320), one process-wide state shared with the host. */
u32 w2c_env_rand(struct w2c_env* e) { (void)e; return (u32)recvx_core_random_next(); }
/* Debug output of the original (printf / write(1, ...)). */
u32 w2c_env_printf(struct w2c_env* e, u32 format, u32 args)
{
    (void)e; (void)args;
    fprintf(stderr, "[original] %s", mem_string(format));
    return 0;
}
u32 w2c_env_write(struct w2c_env* e, u32 fd, u32 buffer, u32 size)
{
    (void)e; (void)fd;
    if (buffer < memory.size) fprintf(stderr, "[original] %.*s", (int)strnlen(mem_string(buffer), size), mem_string(buffer));
    return size;
}

/* ps2_NaTextureFunction.c njSetTexture: the host keeps the current texture
 * list for the draw calls that follow (bhPutModel sets it before drawing). */
u32 w2c_env_njSetTexture(struct w2c_env* e, u32 texlist) { (void)e; current_texlist = texlist; return 1; }

/* ps2_NinjaCnk.c draw entry points: the chunk model is drawn by the host
 * renderer with the current Ninja matrix (pNaMatMatrixStuckPtr). */
static void draw(uint32_t model, int mode)
{
    if (!host.draw_model || !model) return;
    /* The export is the address of the C variable pNaMatMatrixStuckPtr. */
    const uint32_t matrix = read_u32(*w2c_core32_pNaMatMatrixStuckPtr(&instance));
    host.draw_model(host.user, model, (const float*)mem_at(matrix), current_texlist, mode);
}
void w2c_env_njCnkEasyDrawModel(struct w2c_env* e, u32 model) { (void)e; draw(model, 0); }
void w2c_env_njCnkEasyMultiDrawModel(struct w2c_env* e, u32 model) { (void)e; draw(model, 1); }
void w2c_env_njCnkSimpleDrawModel(struct w2c_env* e, u32 model) { (void)e; draw(model, 2); }
void w2c_env_njCnkSimpleMultiDrawModel(struct w2c_env* e, u32 model) { (void)e; draw(model, 3); }

/* sdfunc.c requests. */
void w2c_env_RequestEnemySe(struct w2c_env* e, u32 enemy, u32 position, u32 se)
{
    (void)e;
    if (host.request_enemy_se) host.request_enemy_se(host.user, enemy, position, (int)se);
    else recvx_core32_gap("RequestEnemySe");
}
void w2c_env_CallSystemSe(struct w2c_env* e, u32 unused, u32 se)
{
    (void)e; (void)unused;
    if (host.system_se) host.system_se(host.user, (int)se);
    else recvx_core32_gap("CallSystemSe");
}
void w2c_env_CallPlayerVoice(struct w2c_env* e, u32 voice)
{
    (void)e;
    if (host.player_voice) host.player_voice(host.user, (int)voice);
    else recvx_core32_gap("CallPlayerVoice");
}
void w2c_env_StartVibrationEx(struct w2c_env* e, u32 attribute, u32 number)
{
    (void)e;
    if (host.vibration) host.vibration(host.user, (int)attribute, (int)number);
    else recvx_core32_gap("StartVibrationEx");
}

/* ps2_sg_pad.c pdGetPeripheral: the pad state lives host-side; the module gets
 * its own zeroed PDS_PERIPHERAL so reads never leave module memory. */
u32 w2c_env_pdGetPeripheral(struct w2c_env* e, u32 port)
{
    (void)e; (void)port;
    recvx_core32_gap("pdGetPeripheral");
    return w2c_core32_core32_peripheral_buffer(&instance);
}

/* ---- API -------------------------------------------------------------------- */
int recvx_original_init(const RECVX_ORIGINAL_HOST* h)
{
    if (h) host = *h; else memset(&host, 0, sizeof host);
    if (ready) return 1;
    wasm_rt_init();
    wasm_rt_allocate_memory(&memory, 4096, 4096, false, WASM_DEFAULT_PAGE_SIZE); /* 256 MiB, as linked */
    wasm2c_core32_instantiate(&instance, &env);
    w2c_core32_core32_init(&instance);
    ready = 1;
    return 1;
}

uint8_t* recvx_original_memory(size_t* size)
{
    if (size) *size = (size_t)memory.size;
    return memory.data;
}

int recvx_original_load_room(const uint8_t* rdt, size_t size)
{
    const uint32_t at = w2c_core32_core32_room_begin(&instance, (u32)size);
    if ((uint64_t)at + size > memory.size) return -1;
    memcpy(mem_at(at), rdt, size);
    return (int)w2c_core32_core32_room_finish(&instance);
}

int recvx_original_texture_count(void) { return (int)w2c_core32_core32_texture_count(&instance); }
void recvx_original_texture(int index, uint32_t* texlist, uint32_t* data)
{
    if (texlist) *texlist = w2c_core32_core32_texture_list(&instance, (u32)index);
    if (data) *data = w2c_core32_core32_texture_data(&instance, (u32)index);
}

void recvx_original_set_player(float px, float py, float pz, int ay, int flr_no, int hp)
{
    w2c_core32_core32_set_player(&instance, px, py, pz, (u32)ay, (u32)flr_no, (u32)hp);
}

void recvx_original_set_system_flags(uint32_t sp_flg, uint32_t pt_flg, uint32_t st_flg, uint32_t gm_flg)
{
    w2c_core32_core32_set_system_flags(&instance, sp_flg, pt_flg, st_flg, gm_flg);
}

void recvx_original_control_enemy(void) { w2c_core32_core32_control_enemy(&instance); }

void recvx_original_draw_enemy(const float view[16])
{
    memcpy(mem_at(w2c_core32_core32_view_buffer(&instance)), view, 16 * sizeof(float));
    w2c_core32_core32_draw_enemy(&instance);
}

int recvx_original_enemy_slots(void) { return (int)w2c_core32_core32_enemy_slots(&instance); }

void recvx_original_enemy(int index, RECVX_ORIGINAL_ENEMY* out)
{
    memcpy(out, mem_at(w2c_core32_core32_enemy_info(&instance, (u32)index)), sizeof *out);
}
